package com.example.billing.domain;
import jakarta.persistence.*; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="IdempotencyRecords",uniqueConstraints=@UniqueConstraint(name="IX_IdempotencyRecords_Key",columnNames="Key")) public class IdempotencyRecord { @Id @Column(name="Id") public UUID id; @Column(name="Key",length=200,nullable=false) public String key; @Column(name="RequestHash",length=128,nullable=false) public String requestHash; @Column(name="Status",length=50,nullable=false) public String status; @Column(name="StatusCode") public Integer statusCode; @Column(name="ResponsePaymentId") public UUID responsePaymentId; @Column(name="ErrorCode",length=100) public String errorCode; @Column(name="ErrorMessage",length=500) public String errorMessage; @Column(name="CreatedAt",nullable=false) public OffsetDateTime createdAt; @Column(name="UpdatedAt",nullable=false) public OffsetDateTime updatedAt; }
